DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.guard_account_content()'::regprocedure) INTO f; f:=replace(f,'IF actor.is_demo THEN','IF actor.is_demo THEN IF j->>''season_id'' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM seasons WHERE id=(j->>''season_id'')::uuid AND is_demo) THEN RAISE EXCEPTION ''demo_only''; END IF;'); f:=replace(f,'IF TG_TABLE_NAME=''profiles'' AND TG_OP=''DELETE'' AND coalesce((j->>''is_demo'')::boolean,false) THEN','IF TG_TABLE_NAME=''profiles'' AND TG_OP=''DELETE'' AND coalesce((j->>''is_demo'')::boolean,false) AND NOT actor.is_admin THEN'); EXECUTE f; END $$;
CREATE FUNCTION public.register_saved_proof(_path text,_fingerprint text,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF split_part(_path,'/',1)<>_user::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='proofs' AND name=_path) THEN RAISE EXCEPTION 'forbidden'; END IF; IF EXISTS(SELECT 1 FROM proof_fingerprints WHERE fingerprint=_fingerprint AND user_id<>_user) THEN INSERT INTO admin_suspicious_activity(user_id,kind,detail,is_demo) SELECT _user,'duplicate_proof',jsonb_build_object('path',_path),is_demo FROM profiles WHERE id=_user; END IF; INSERT INTO proof_fingerprints(path,user_id,fingerprint,is_demo) SELECT _path,_user,_fingerprint,is_demo FROM profiles WHERE id=_user ON CONFLICT(path) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.register_saved_proof(text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.register_saved_proof(text,text,uuid) TO service_role;
CREATE FUNCTION public.admin_clear_demo() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids jsonb; t text; BEGIN PERFORM public._require_admin(); PERFORM pg_advisory_xact_lock(hashtext('lezgo-demo-seed')); SELECT coalesce(jsonb_agg(p.id),'[]') INTO ids FROM profiles p JOIN auth.users u ON u.id=p.id WHERE p.is_demo AND u.email<>'demo@lezgo.app';
FOREACH t IN ARRAY ARRAY['announcement_receipts','announcements','proof_fingerprints','activity_events','admin_suspicious_activity','reports','post_hides','post_reactions','respects','nudges','buddy_requests','buddy_links','buddy_safety_reports','detox_duels','screen_time_logs','detox_sessions','bonus_points','boss_hits','boss_entries','badges','season_trophies','season_reminders','time_capsules','lift_sets','posts','checkins','daily_scores','day_extras','challenge_squad_members','challenge_squads','crew_members','user_habits','season_entries','user_preferences','creator_referrals','challenges','crews','bosses','seasons','user_roles'] LOOP EXECUTE format('DELETE FROM public.%I WHERE is_demo',t); END LOOP;
UPDATE profiles SET demo_today=NULL,onboarded=false WHERE is_demo; PERFORM public._admin_audit('clear_demo',NULL,jsonb_build_object('players',jsonb_array_length(ids)+1)); RETURN jsonb_build_object('auth_ids',ids); END $$;
REVOKE ALL ON FUNCTION public.admin_clear_demo() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_clear_demo() TO authenticated;
CREATE FUNCTION public.admin_seed_demo(_people jsonb,_replace boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; person jsonb; ids uuid[]:='{}'; sid uuid; company_sid uuid; creator_sid uuid; main_ch uuid; company_ch uuid; creator_ch uuid; cr uuid; bcc uuid; duo uuid; sq uuid; h record; i int; j int; d date; sd date; ed date; old_sid uuid; bid uuid; b record; lvl jsonb; t text; n int; pid uuid; post_ids uuid[]:='{}'; langs text[]:=ARRAY['en','fr','ar','aeb']; bodies text[]:=ARRAY['Showed up even when I did not feel like it. One more go.','Un petit effort, tous les jours. On continue !','خطوة صغيرة اليوم، تقدّم كبير غدًا.','قهوة بلا سكّر والنهار بدا مليح. يلّا نكمّلوا!']; habit_keys text[];BEGIN uid:=public._require_admin(); PERFORM pg_advisory_xact_lock(hashtext('lezgo-demo-seed')); IF jsonb_typeof(_people)<>'array' OR jsonb_array_length(_people)<>40 THEN RAISE EXCEPTION 'invalid_demo_players'; END IF;
IF _replace THEN PERFORM public.admin_clear_demo(); ELSIF EXISTS(SELECT 1 FROM seasons WHERE slug='demo-winter-arc') THEN PERFORM public._admin_audit('seed_demo_existing',NULL,'{}'); RETURN jsonb_build_object('ok',true,'existing',true); END IF;
SELECT id,starts_on,ends_on INTO old_sid,sd,ed FROM seasons WHERE slug='winter-arc-2026'; IF old_sid IS NULL THEN SELECT id,starts_on,ends_on INTO old_sid,sd,ed FROM seasons WHERE NOT challenge_owned ORDER BY starts_on LIMIT 1; END IF; IF old_sid IS NULL THEN RAISE EXCEPTION 'no_season'; END IF;
i:=0; FOR person IN SELECT value FROM jsonb_array_elements(_people) LOOP IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=(person->>'id')::uuid AND email=person->>'email' AND (email='demo@lezgo.app' OR email ~ '^player[0-9]+@demo\.lezgo\.invalid$')) THEN RAISE EXCEPTION 'invalid_demo_player'; END IF; ids:=array_append(ids,(person->>'id')::uuid); UPDATE profiles SET handle=person->>'handle',display_name=person->>'name',country_code=person->>'country',city=person->>'city',timezone=CASE person->>'country' WHEN 'FR' THEN 'Europe/Paris' WHEN 'CA' THEN 'America/Toronto' WHEN 'DE' THEN 'Europe/Berlin' WHEN 'AE' THEN 'Asia/Dubai' WHEN 'EG' THEN 'Africa/Cairo' ELSE 'Africa/Tunis' END,language=langs[1+(i%4)],onboarded=true,is_admin=false,is_demo=true,demo_today=sd+13,faith_public=false,show_on_public_board=true,birth_date='1997-06-15',gender=CASE WHEN i%2=0 THEN 'man' ELSE 'woman' END,equipment=ARRAY['dumbbell','pullup','bodyweight'],max_dumbbell_kg=10,created_at=(sd+(i%3))::timestamp AT TIME ZONE 'Africa/Tunis' WHERE id=(person->>'id')::uuid; i:=i+1; END LOOP;
FOR j IN 1..3 LOOP INSERT INTO challenge_squads(challenge_id,name,is_demo) VALUES(company_ch,'Squad '||j,true) RETURNING id INTO sq; INSERT INTO challenge_squad_members(squad_id,user_id,is_demo) SELECT sq,ids[g],true FROM generate_series((j-1)*9+1,least(j*9,25))g; END LOOP;
FOR i IN 1..40 LOOP habit_keys:=CASE WHEN i=1 THEN ARRAY['train','learn','sleep','no_sugar','salat'] WHEN i%7=0 THEN ARRAY['salat','quran'] WHEN i%4=0 THEN ARRAY['run','water','sleep'] WHEN i%3=0 THEN ARRAY['read','coffee'] ELSE ARRAY['train','learn','sleep'] END; INSERT INTO user_habits(user_id,season_id,template_id,kind,target,unit,position,is_demo) SELECT ids[i],sid,ht.id,ht.kind,ht.default_target,ht.unit,k.ord::int-1,true FROM unnest(habit_keys) WITH ORDINALITY k(key,ord) JOIN habit_templates ht ON ht.key=k.key;
FOR h IN SELECT * FROM user_habits WHERE user_id=ids[i] AND season_id=sid LOOP FOR j IN 0..13 LOOP IF i=1 AND j<5 OR i<>1 AND (i+j)%9=0 THEN CONTINUE; END IF; INSERT INTO checkins(user_id,user_habit_id,day,value,detail,created_at,is_demo) VALUES(ids[i],h.id,sd+j,CASE WHEN h.kind='salat' THEN 5 WHEN i=1 OR (i+j)%5<>0 THEN h.target ELSE h.target*0.5 END,CASE WHEN h.kind='salat' THEN '{"prayers":{"fajr":"on_time","dhuhr":"on_time","asr":"on_time","maghrib":"on_time","isha":"on_time"}}'::jsonb ELSE NULL END,(sd+j)::timestamp+interval '20 hours',true); END LOOP; END LOOP;
FOR i IN 1..12 LOOP INSERT INTO lift_sets(user_id,exercise_id,day,weight,reps,unit,result,is_demo,created_at) SELECT ids[i],ex.id,sd+2+g*3,CASE WHEN ex.equipment='bodyweight' THEN NULL ELSE 10 END,10+g+i%3,'kg',CASE WHEN g=0 THEN 'match' ELSE 'beat' END,true,(sd+2+g*3)::timestamp+interval '18 hours' FROM lift_exercises ex CROSS JOIN generate_series(0,3)g WHERE ex.key IN('goblet_squat','floor_press','pullups'); END LOOP;
UPDATE day_extras e SET lift_prs=least(3,(SELECT count(*) FROM lift_sets ls WHERE ls.user_id=e.user_id AND ls.day=e.day AND result='beat')) WHERE e.is_demo;
FOR i IN 1..60 LOOP n:=1+(i%40); INSERT INTO posts(user_id,season_id,crew_id,type,body,stats,visibility,day,is_demo,created_at) VALUES(ids[n],sid,(SELECT crew_id FROM crew_members m JOIN crews c ON c.id=m.crew_id WHERE m.user_id=ids[n] AND c.season_id=sid LIMIT 1),CASE i%3 WHEN 0 THEN 'proof' WHEN 1 THEN 'thought' ELSE 'win' END,bodies[1+(i%4)],jsonb_build_object('demo',true),'everyone',sd+(i%14),true,(sd+(i%14))::timestamp+make_interval(hours=>12+i%8)) RETURNING id INTO pid;post_ids:=array_append(post_ids,pid); INSERT INTO post_reactions(post_id,user_id,kind,is_demo) SELECT pid,ids[1+((i+g)%40)],(ARRAY['respect','beast','lol','legend'])[1+(g%4)],true FROM generate_series(1,3)g ON CONFLICT DO NOTHING; END LOOP;
FOR i IN 1..3 LOOP INSERT INTO reports(post_id,reporter,reason,is_demo) SELECT post_ids[i],ids[g],(ARRAY['Fake proof','Spam link','Rude comment'])[i],true FROM generate_series(10,13)g; UPDATE posts SET hidden=true WHERE id=post_ids[i]; END LOOP;
FOR i IN 1..40 LOOP PERFORM public.recompute_day(ids[i],sid,sd+13); END LOOP;
FOR b IN SELECT * FROM bosses WHERE season_id=sid AND week_no IN(1,2) LOOP FOR i IN 1..16 LOOP INSERT INTO boss_hits(boss_id,user_id,amount,created_at,is_demo) VALUES(b.id,ids[i],CASE WHEN b.week_no=1 THEN 40+i*5 ELSE 200+i*20 END,(sd+CASE WHEN b.week_no=1 THEN 5 ELSE 12 END)::timestamp+interval '12 hours',true); INSERT INTO boss_entries(boss_id,user_id,level,is_demo) VALUES(b.id,ids[i],'rookie',true) ON CONFLICT DO NOTHING; PERFORM public._sync_boss(ids[i],b.id); IF b.week_no=1 THEN SELECT l INTO lvl FROM jsonb_array_elements(b.levels)l WHERE l->>'key'='rookie'; IF (SELECT progress FROM boss_entries WHERE boss_id=b.id AND user_id=ids[i])>=(lvl->>'target')::numeric THEN INSERT INTO bonus_points(user_id,season_id,boss_id,level,points,awarded_at,is_demo) VALUES(ids[i],sid,b.id,'rookie',(lvl->>'bonus')::int,sd+5,true) ON CONFLICT DO NOTHING; UPDATE boss_entries SET completed_at=sd+5 WHERE boss_id=b.id AND user_id=ids[i]; INSERT INTO badges(user_id,season_id,key,is_demo) VALUES(ids[i],sid,'boss_ko',true) ON CONFLICT DO NOTHING; END IF; END IF; END LOOP; END LOOP;
FOREACH t IN ARRAY ARRAY['daily_scores','badges','bonus_points','boss_entries','activity_events','admin_suspicious_activity'] LOOP EXECUTE format('UPDATE public.%I SET is_demo=true WHERE user_id=ANY($1)',t) USING ids; END LOOP;
PERFORM public._admin_audit('seed_demo',sid::text,jsonb_build_object('profiles',40,'posts',60,'history_days',14,'crews',6)); RETURN jsonb_build_object('ok',true,'season',sid); END $$;
REVOKE ALL ON FUNCTION public.admin_seed_demo(jsonb,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_seed_demo(jsonb,boolean) TO authenticated;