INSERT INTO user_preferences(user_id,active_challenge_id,equipment,max_dumbbell,is_demo) VALUES(ids[i],main_ch,ARRAY['dumbbell','pullup','bodyweight'],10,true) ON CONFLICT(user_id) DO UPDATE SET active_challenge_id=main_ch,is_demo=true;
INSERT INTO day_extras(user_id,day,proof_posted,chaos_done,chaos_spins,is_demo) SELECT ids[i],sd+g,(i+g)%3=0,(i+g)%4=0,CASE WHEN (i+g)%4=0 THEN 1 ELSE 0 END,true FROM generate_series(0,13)g; END LOOP;
INSERT INTO bosses(season_id,week_no,slug,name,rule,metric,exercise_key,levels,starts_at,ends_at,color,is_demo) SELECT sid,week_no,slug,name,rule,metric,exercise_key,levels,starts_at,ends_at,color,true FROM bosses WHERE season_id=old_sid;
